// Static synthetic proposal only. No API calls, account edits or preference persistence.
const params=new URLSearchParams(location.search);
const variant=params.get('variant')==='B'?'B':'A';
const view=['counterparties','expenses','notifications','settings'].includes(params.get('view'))?params.get('view'):'settings';
const theme=params.get('theme')==='dark'?'dark':'light';
document.body.classList.toggle('variant-b',variant==='B');
const href=(v)=>`prototype.html?variant=${variant}&view=${v}&theme=${document.documentElement.dataset.theme}`;
document.querySelectorAll('[data-view]').forEach(a=>{a.href=href(a.dataset.view);if(a.dataset.view===view)a.setAttribute('aria-current','page');});
const themes=(suffix='')=>`<fieldset><legend>Chế độ giao diện</legend><div class="theme-options">${[['light','Sáng'],['dark','Tối'],['system','Theo thiết bị']].map(([value,label])=>`<label><input type="radio" name="theme${suffix}" value="${value}" ${value==='system'?'checked':''}><span>${label}</span></label>`).join('')}</div><p class="theme-caption">Đang theo thiết bị · ${theme==='dark'?'Tối':'Sáng'}</p></fieldset>`;
const titles={settings:'Cài đặt',counterparties:'Đối tác',expenses:'Chi phí chung',notifications:'Thông báo'};
const quick=variant==='B'?`<details class="theme-menu"><summary aria-label="Chọn giao diện" title="Chọn giao diện">◐</summary><div class="theme-popup">${themes('quick')}</div></details>`:'';
const create=view==='counterparties'?'<button class="primary" data-demo="form">Thêm đối tác</button>':view==='expenses'?'<button class="primary" data-demo="form">Thêm chi phí</button>':view==='notifications'?'<button data-demo="notification">Đánh dấu đã đọc</button>':'';
let content='';
if(view==='settings') content=`<section class="card"><div class="section-heading"><div><h2>Giao diện</h2><p class="muted">Lựa chọn riêng trên trình duyệt này.</p></div></div>${themes('settings')}</section><section class="card"><div class="setting-row"><div><h2>Tài khoản của tôi</h2><p>Chủ tài khoản mẫu</p><p class="muted">owner_demo · Chủ tài khoản</p></div><button data-demo="account">Đổi mật khẩu</button></div></section><section class="card"><div class="section-heading"><div><h2>Quản trị người dùng</h2><p class="muted">Quản lý tài khoản phụ và quyền truy cập.</p></div><button data-demo="account">Thêm tài khoản</button></div><article class="row"><div><h3>Tài khoản mẫu</h3><p>editor_demo · Biên tập</p></div><button data-demo="account">Quản lý</button></article><details><summary>Tài khoản đã vô hiệu hóa (2)</summary><p class="muted">Thu gọn để bảo toàn lịch sử. Không thể đăng nhập.</p></details></section>`;
if(view==='counterparties') content=`<form class="toolbar" role="search"><label><span hidden>Tìm tên hoặc ghi chú đối tác</span><input aria-label="Tìm tên hoặc ghi chú đối tác" placeholder="Tìm tên hoặc ghi chú…"></label><button type="submit">Tìm kiếm</button><span class="muted">3 đối tác</span></form><section class="list" aria-label="Danh sách đối tác">${[['Đối tác Minh An','Liên hệ đối chiếu vào cuối tháng'],['Đối tác có tên dài để kiểm tra khả năng đọc đầy đủ trên màn hình nhỏ','Ghi chú mẫu có nhiều ngữ cảnh; vẫn đọc trọn nội dung.'],['Đối tác Bình Minh','']].map(([name,note])=>`<article class="row"><div><h2>${name}</h2>${note?`<p>${note}</p>`:''}</div><div class="row-actions"><button data-demo="edit">Chỉnh sửa</button><button aria-label="Thao tác khác với ${name}" data-demo="menu">⋯</button></div></article>`).join('')}</section><nav class="pagination" aria-label="Phân trang"><span>Trang 1 / 1 · 3 đối tác</span></nav>`;
if(view==='expenses') content=`<section class="card"><div class="section-heading"><div><h2>Chi phí tháng 10</h2><p class="muted">3 giao dịch · Dữ liệu giả</p></div><strong class="total">3.000.000 ₫</strong></div><details><summary>Phân bổ danh mục</summary><div class="distribution">${[['Vận hành','1.500.000',50],['Văn phòng','900.000',30],['Dịch vụ','600.000',20]].map(([name,amount,percent])=>`<div class="distribution-row"><p>${name}</p><span>${amount} ₫ · ${percent}%</span><div class="bar"><span style="width:${percent}%"></span></div></div>`).join('')}</div></details></section><section class="list" aria-label="Danh sách chi phí chung">${[['Vận hành','1.500.000','Thuê không gian làm việc'],['Văn phòng','900.000','Vật tư văn phòng'],['Dịch vụ','600.000','Dịch vụ hỗ trợ']].map(([name,amount,note])=>`<article class="row money-row"><div><h2>${name}</h2><p>01/10/2026 · ${note}</p></div><div class="row-actions"><strong class="money">${amount} ₫</strong><button data-demo="menu" aria-label="Thao tác khác với chi phí ${name}">⋯</button></div></article>`).join('')}</section>`;
if(view==='notifications') content=`<div class="toolbar"><a class="pill" href="#all" aria-current="page">Tất cả</a><a class="pill" href="#unread">Chưa đọc (2)</a></div><section class="list" aria-label="Danh sách thông báo">${[['Đến ngày thu lãi','Minh An · 03/10/2026','30.000 ₫',false],['Nhắc hạn khoản vay','Bình Minh · 04/10/2026','1.000.000 ₫',false],['Thông báo đã đọc','Minh An · 01/10/2026','',true]].map(([name,note,money,read])=>`<article class="row notification-row ${read?'read':''}"><div><h2>${name}</h2><small>${read?'Đã đọc':'Chưa đọc'}</small><p>${note}${money?` · ${money}`:''}</p></div><div class="row-actions"><button data-demo="notification">Xem khoản vay</button></div></article>`).join('')}</section><section class="card" style="margin-top:20px"><div class="setting-row"><div><h2>Thông báo trên thiết bị</h2><p class="muted">Chưa bật. Chỉ xin quyền khi bạn chọn bật.</p></div><button data-demo="permission">Cài đặt thông báo</button></div></section>`;
document.querySelector('main').innerHTML=`<div class="notice"><span>C83 · Phương án ${variant} · Mọi dữ liệu là giả, chưa sửa webapp.</span><a href="proposal.html">So sánh A / B</a></div><header class="heading"><div><h1>${titles[view]}</h1>${view==='counterparties'?'<p class="muted">Tìm liên hệ và chỉnh sửa khi cần.</p>':''}</div><div class="heading-actions">${quick}${create}</div></header>${content}<p id="demo-status" role="status" class="muted"></p>`;
if(params.get('stress')==='true'){
  document.querySelectorAll('.list .row h2').forEach(e=>e.textContent='C83 '+ 'L'.repeat(view==='expenses'?76:116));
  document.querySelectorAll('.list .row p').forEach(e=>e.textContent='N'.repeat(500));
}
document.querySelectorAll('input[type=radio]').forEach(input=>input.addEventListener('change',()=>{
  const value=input.value; const resolved=value==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):value;
  document.documentElement.dataset.theme=resolved;
  document.querySelectorAll('input[type=radio]').forEach(other=>other.checked=other.value===value);
  document.querySelectorAll('.theme-caption').forEach(c=>c.textContent=value==='system'?`Đang theo thiết bị · ${resolved==='dark'?'Tối':'Sáng'}`:`Đang dùng giao diện ${resolved==='dark'?'Tối':'Sáng'}`);
  document.querySelectorAll('[data-view]').forEach(a=>a.href=href(a.dataset.view));
  document.querySelector('#demo-status').textContent='Đã đổi bản xem mẫu. Chưa lưu tùy chọn của webapp.';
}));
document.querySelectorAll('[data-demo]').forEach(button=>button.addEventListener('click',()=>document.querySelector('#demo-status').textContent='Đây là bản xem bố cục. Luồng nghiệp vụ sẽ được triển khai và kiểm thử trong C84 sau phê duyệt.'));
document.querySelector('form')?.addEventListener('submit',event=>{event.preventDefault();document.querySelector('#demo-status').textContent='Ô tìm là mô phỏng bố cục; không gọi database.';});
